use anyhow::Result;
use vk_api::{auth, VkClient};

#[tokio::main]
async fn main() -> Result<()> {
    println!("╔════════════════════════════════════════════════════════╗");
    println!("║       VK Music - Информация о пользователе             ║");
    println!("╚════════════════════════════════════════════════════════╝\n");

    // Шаг 1: Авторизация
    let token = auth::interactive_auth()?;

    // Шаг 2: Создание клиента
    let client = VkClient::new(token);

    // Шаг 3: Получение информации о текущем пользователе
    println!("Получаем информацию о пользователе...\n");

    let user = client.get_me().await?;

    // Шаг 4: Вывод результатов
    println!("╔════════════════════════════════════════════════════════╗");
    println!("║                   Ваш профиль                          ║");
    println!("╠════════════════════════════════════════════════════════╣");
    println!("║ ID:   {:<49} ║", user.id);
    println!("║ Имя:  {:<49} ║", user.full_name());
    println!("╚════════════════════════════════════════════════════════╝\n");

    Ok(())
}
